    grid-template-columns: 64px minmax(0, 1fr);
    align-items: stretch;
    gap: 1rem;
    padding: 1rem;
    min-width: 0;
    background: var(
        --app-widget-bg,
        var(--mat-sys-surface-container-high)
    );
    border-radius: 14px;
    border: 1px solid var(--app-separator, var(--mat-sys-outline-variant));
    box-shadow: var(--app-widget-shadow, none);
    transition:
        background 0.18s ease,
        border-color 0.18s ease,
        box-shadow 0.2s ease,
        transform 0.2s ease;

    &--clickable {
        cursor: pointer;

        &:focus-visible {
            outline: 2px solid var(--mat-sys-primary);
            outline-offset: 2px;
        }
    }

    &:hover {
        background: var(--app-selection-surface);
        border-color: color-mix(
            in srgb,
            var(--app-selection-border) 72%,
            transparent
        );
    }

    &--unavailable {
        cursor: default;
    }

