        display: flex;
        align-items: center;
        gap: 8px;
        font-weight: 600;
        font-size: 0.78rem;
        letter-spacing: 0.04em;
        color: var(--epg-text-primary);
        text-transform: uppercase;

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
            color: var(--epg-accent);
        }

        .minimized-summary {
            font-size: 0.78rem;
            font-weight: 500;
            text-transform: none;
            letter-spacing: normal;
            color: var(--epg-text-secondary);
        }
    }

    .header-actions {
        display: flex;
        align-items: center;
        gap: 0;
    }

    .minimize-btn,
    .dismiss-all-btn {
        width: 28px;
        height: 28px;
        padding: 0;
        line-height: 28px;
        border-radius: 8px;
        color: var(--epg-text-tertiary);

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
        }
    }
}

.epg-progress-panel--minimized {
    width: auto;
    min-width: 180px;
    max-width: 300px;

    .panel-header {
        border-bottom: none;
    }
}

