    padding: 6px 10px;
    transition: background 0.15s ease;
    position: relative;

    &:not(:last-child) {
        border-bottom: 1px solid var(--epg-separator);
    }

    &:hover {
        background: var(--epg-item-hover);
    }

    .item-header {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 4px;

        mat-icon {
            font-size: 16px;
            width: 16px;
            height: 16px;
            flex-shrink: 0;
        }

        .item-url {
            flex: 1;
            font-size: 0.78rem;
            font-weight: 500;
            white-space: nowrap;
            overflow: hidden;
