        opacity: 1;
    }

    &.status-loading .item-header mat-icon {
        color: var(--epg-accent);
    }

    &.status-complete .item-header mat-icon {
        color: var(--epg-success);
    }

    &.status-error .item-header mat-icon {
        color: var(--epg-error);
    }
}

