    .stat-badge {
        display: inline-flex;
        align-items: center;
        gap: 3px;
        font-size: 0.7rem;
        font-weight: 500;
        color: var(--epg-text-tertiary);

        mat-icon {
            font-size: 12px;
            width: 12px;
            height: 12px;
        }
    }

    .error-text {
        font-size: 0.72rem;
        color: var(--epg-error);
    }
}

.queue-section {
    margin: 2px 0 0;
    padding: 6px 10px 8px;
    border-top: 1px solid var(--epg-separator);
}

.queue-header {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 4px;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--epg-text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.04em;

    mat-icon {
        font-size: 14px;
        width: 14px;
        height: 14px;
        color: var(--epg-queued);
    }
}

.queue-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.queue-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 3px 6px;
    border-radius: 6px;
    color: var(--epg-text-tertiary);

    .queue-position {
        width: 16px;
        text-align: center;
        font-size: 0.68rem;
        font-weight: 700;
        color: var(--epg-queued);
    }

    .queue-url {
        flex: 1;
        font-size: 0.72rem;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .dismiss-btn {
        width: 22px;
        height: 22px;
        padding: 0;
        line-height: 22px;
        color: var(--epg-text-tertiary);

        mat-icon {
            font-size: 14px;
            width: 14px;
            height: 14px;
        }
    }
}

@media (max-width: 700px) {
    .epg-progress-panel {
        left: 76px;
        right: 12px;
        bottom: 12px;
        width: auto;
        max-width: none;
    }
}

@media (max-width: 640px) {
    .epg-progress-panel {
        left: 12px;
    }
}

