/**
 * Fetch EPG from a single URL using worker thread
 * The worker handles both parsing AND database operations
 */
private static async fetchEpgFromUrl(url: string): Promise<void> {
    // Skip if already fetched this session
    if (this.fetchedUrls.has(url)) {
        console.log(
            this.loggerLabel,
            `Skipping already fetched URL: ${url}`
        );
        return;
    }

    return new Promise((resolve, reject) => {
        let worker: Worker;
        try {
            worker = this.createEpgWorker();
        } catch (error) {
            console.error(
                this.loggerLabel,
                'Failed to create worker:',
                error
            );
            reject(error);
            return;
        }

        this.workers.set(url, worker);

        worker.on(
            'message',
            async (message: {
                type: string;
                error?: string;
                url?: string;
                stats?: { totalChannels: number; totalPrograms: number };
            }) => {
                try {
                    switch (message.type) {
                        case 'READY':
                            // Notify renderer that loading started
                            this.sendProgressToRenderer(url, 'loading', {
                                totalChannels: 0,
                                totalPrograms: 0,
                            });
                            worker.postMessage({ type: 'FETCH_EPG', url });
                            break;

                        case 'EPG_PROGRESS':
                            if (message.stats) {
                                // Forward progress to renderer
                                this.sendProgressToRenderer(
                                    url,
                                    'loading',
                                    message.stats
                                );
                            }
                            break;

                        case 'EPG_COMPLETE':
                            console.log(
                                this.loggerLabel,
                                `EPG parsing complete for ${url}:`,
                                message.stats
                            );
                            // Notify renderer of completion
                            this.sendProgressToRenderer(
                                url,
                                'complete',
                                message.stats
                            );
                            this.fetchedUrls.add(url);
                            worker.terminate();
                            this.workers.delete(url);
                            resolve();
                            break;

                        case 'EPG_ERROR':
                            console.error(
                                this.loggerLabel,
                                'Worker error:',
                                message.error
                            );
                            // Notify renderer of error
                            this.sendProgressToRenderer(
                                url,
                                'error',
                                undefined,
                                message.error
                            );
                            worker.terminate();
                            this.workers.delete(url);
                            reject(
                                new Error(message.error || 'Unknown error')
                            );
                            break;
                    }
                } catch (err) {
                    console.error(
                        this.loggerLabel,
                        'Error handling message:',
                        err
                    );
                    reject(err);
                }
            }
        );

        worker.on('error', (error) => {
            console.error(this.loggerLabel, 'Worker error event:', error);
            worker.terminate();
            this.workers.delete(url);
            reject(error);
        });

        worker.on('exit', (code) => {
            if (code !== 0) {
                console.error(
                    this.loggerLabel,
                    `Worker stopped with exit code ${code}`
                );
            }
        });
    });
}

