                            // Notify renderer that loading started
                            this.sendProgressToRenderer(url, 'loading', {
                                totalChannels: 0,
                                totalPrograms: 0,
                            });
                            worker.postMessage({ type: 'FETCH_EPG', url });
                            break;

                        case 'EPG_PROGRESS':
                            if (message.stats) {
                                // Forward progress to renderer
                                this.sendProgressToRenderer(
                                    url,
                                    'loading',
                                    message.stats
                                );
                            }
                            break;

                        case 'EPG_COMPLETE':
                            console.log(
                                this.loggerLabel,
                                `EPG parsing complete for ${url}:`,
                                message.stats
                            );
                            // Notify renderer of completion
                            this.sendProgressToRenderer(
                                url,
                                'complete',
                                message.stats
                            );
                            this.fetchedUrls.add(url);
                            worker.terminate();
                            this.workers.delete(url);
                            settle(() => resolve());
                            break;

                        case 'EPG_ERROR':
                            console.error(
                                this.loggerLabel,
                                'Worker error:',
                                message.error
                            );
                            // Notify renderer of error
                            this.sendProgressToRenderer(
                                url,
                                'error',
                                undefined,
                                message.error
                            );
                            worker.terminate();
                            this.workers.delete(url);
                            settle(() =>
                                reject(
                                    new Error(
                                        message.error || 'Unknown error'
                                    )
                                )
                            );
                            break;
                    }
                } catch (err) {
                    console.error(
                        this.loggerLabel,
                        'Error handling message:',
                        err
                    );
                    this.sendProgressToRenderer(
                        url,
                        'error',
                        undefined,
                        err instanceof Error ? err.message : String(err)
                    );
                    worker.terminate();
                    this.workers.delete(url);
                    settle(() => reject(err));
                }
            }
        );

        worker.on('error', (error) => {
            console.error(this.loggerLabel, 'Worker error event:', error);
            this.sendProgressToRenderer(
                url,
                'error',
                undefined,
                error.message
            );
            worker.terminate();
            this.workers.delete(url);
            settle(() => reject(error));
        });

        worker.on('exit', (code) => {
            // If the worker exits without emitting EPG_COMPLETE/EPG_ERROR,
            // settle the promise so the outer sequential loop can advance
            // instead of hanging forever.
            if (settled) return;
            const errorMessage = `Worker exited unexpectedly (code ${code})`;
            console.error(this.loggerLabel, `${errorMessage}: ${url}`);
            this.sendProgressToRenderer(
                url,
                'error',
                undefined,
                errorMessage
            );
            this.workers.delete(url);
            settle(() => reject(new Error(errorMessage)));
        });
    });
}

