:host {
    // Theme-aware tokens — map to app design tokens
    --epg-panel-bg: var(--app-widget-bg);
    --epg-shadow: var(--app-widget-shadow);
    --epg-text-primary: var(--app-heading-color);
    --epg-text-secondary: var(--app-body-color);
    --epg-text-tertiary: var(--app-muted-color);
    --epg-accent: var(--app-selection-color);
    --epg-accent-glow: color-mix(
        in srgb,
        var(--app-selection-color) 40%,
        transparent
    );
    --epg-item-hover: var(--app-hover-overlay);
    --epg-separator: var(--app-separator);

    // Status colors — semantic, not theme-dependent
    --epg-success: #22c55e;
    --epg-error: #ef4444;
    --epg-queued: #a78bfa;
}

.epg-progress-panel {
    position: fixed;
    bottom: 20px;
    left: 76px;
    width: 300px;
    max-width: calc(100vw - 96px);
    background: var(--epg-panel-bg);
    border-radius: 12px;
    border: 1px solid var(--epg-separator);
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.08),
        0 8px 24px rgba(0, 0, 0, 0.18),
        0 16px 48px rgba(0, 0, 0, 0.12);
    z-index: 900;
    overflow: hidden;
    animation: slideInFromLeft 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideInFromLeft {
    from {
        opacity: 0;
        transform: translateX(-16px) scale(0.97);
    }
    to {
        opacity: 1;
        transform: translateX(0) scale(1);
    }
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 8px 8px 12px;
    border-bottom: 1px solid var(--epg-separator);

    .header-title {
        display: flex;
        align-items: center;
        gap: 8px;
        font-weight: 600;
        font-size: 0.78rem;
        letter-spacing: 0.04em;
        color: var(--epg-text-primary);
        text-transform: uppercase;

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
            color: var(--epg-accent);
        }

        .minimized-summary {
            font-size: 0.78rem;
            font-weight: 500;
            text-transform: none;
            letter-spacing: normal;
            color: var(--epg-text-secondary);
        }
    }

    .header-actions {
        display: flex;
        align-items: center;
        gap: 0;
    }

    .minimize-btn,
    .dismiss-all-btn {
        width: 28px;
        height: 28px;
        padding: 0;
        line-height: 28px;
        border-radius: 8px;
        color: var(--epg-text-tertiary);

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
        }
    }
}

